// Pure logic for the Simple Magic Trackpad panel, the same rules as the
// Python settings app (app/mac_trackpad_settings/core.py): no Qt here, so it
// can be checked under node (omarchy/tests/model.test.mjs).
//
// - daemon.json: parsed, only the changed switch's key set, every other key
//   kept (written back by Panel.qml through FileView, atomically).
// - accel.conf: the "# generated by mac_curves.py: ..." header is parsed so
//   the values the panel doesn't show (gains, resolution, ...) pass through.
// - mac-trackpad-accel: the `set` arguments, every value explicit.

// The tracking speeds macOS has curves for, one slider position each.
var POINTER_POSITIONS = [0.0, 0.125, 0.5, 0.6875, 0.875, 1.0, 1.5, 2.0, 2.5, 3.0]

// The scroll speeds of the macOS slider.
var SCROLL_POSITIONS = [0.0, 0.0735, 0.1265, 0.1838, 0.3125, 0.4412, 0.5882, 1.0]

var MOMENTUM_KEY = "momentum"
var DRAG_KEY = "threeFingerDrag"

// accel.conf header values -> mac_curves.py option, in `set` order.
var ACCEL_OPTIONS = [
  ["pointerSetting", "--pointer-setting"],
  ["pointerGain", "--pointer-gain"],
  ["scrollSetting", "--scroll-setting"],
  ["scrollGain", "--scroll-gain"],
  ["kwinScrollFactor", "--kwin-scroll-factor"],
  ["res", "--res"],
  ["step", "--step"]
]

// As mac_curves.py's argparse defaults; the two settings are replaced by
// mac-params.json's when it can be read (accelDefaults()).
var ACCEL_DEFAULTS = {
  pointerSetting: 1.5,
  pointerGain: 1.0,
  scrollSetting: 0.3125,
  scrollGain: 1.0,
  kwinScrollFactor: 1.4,
  res: 47.0,
  step: 0.25
}

// Slider position whose value is closest to value; ties go to the lower one.
function nearestPosition(value, positions) {
  var best = 0
  for (var i = 1; i < positions.length; i++) {
    if (Math.abs(positions[i] - value) < Math.abs(positions[best] - value)) best = i
  }
  return best
}

// The speed of a slider position, clamped to the valid range.
function positionValue(position, positions) {
  var i = Math.round(Number(position))
  if (!isFinite(i)) i = 0
  return positions[Math.min(Math.max(i, 0), positions.length - 1)]
}

// Short decimal text for a number: 1.5, 0.3125, 47 (as core.format_number).
function formatNumber(v) {
  var s = Number(v).toFixed(6).replace(/0+$/, "").replace(/\.$/, "")
  return s === "" || s === "-0" ? "0" : s
}

var NUM = "([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)"
var HEADER_FIELDS = {
  pointerSetting: new RegExp("\\bpointer setting " + NUM),
  scrollSetting: new RegExp("\\bscroll setting " + NUM),
  res: new RegExp("\\bres " + NUM + " units/mm"),
  pointerGain: new RegExp("\\bpointer gain " + NUM),
  scrollGain: new RegExp("\\bscroll gain " + NUM),
  kwinScrollFactor: new RegExp("\\bkwin scroll factor " + NUM)
}

// Curve values from accel.conf's comment header (plus step from
// motion_step=). Only the fields found are returned.
function parseHeader(text) {
  var comments = []
  var out = {}
  var lines = String(text || "").split(/\r?\n/)
  for (var i = 0; i < lines.length; i++) {
    var s = lines[i].trim()
    if (s.charAt(0) === "#") {
      comments.push(s.replace(/^#+/, "").trim())
    } else if (s.indexOf("motion_step=") === 0) {
      var step = parseFloat(s.slice("motion_step=".length))
      if (isFinite(step)) out.step = step
    }
  }
  var joined = comments.join(" ")
  if (joined.indexOf("generated by mac_curves.py") < 0) return out
  for (var key in HEADER_FIELDS) {
    var m = HEADER_FIELDS[key].exec(joined)
    if (m) out[key] = parseFloat(m[1])
  }
  return out
}

// ACCEL_DEFAULTS with the two settings from mac-params.json text, if valid.
function accelDefaults(paramsText) {
  var out = {}
  for (var k in ACCEL_DEFAULTS) out[k] = ACCEL_DEFAULTS[k]
  var params = null
  try { params = JSON.parse(paramsText) } catch (e) { params = null }
  if (params && typeof params === "object") {
    var pairs = [["pointerSetting", "pointer_setting"], ["scrollSetting", "scroll_setting"]]
    for (var i = 0; i < pairs.length; i++) {
      var v = Number(params[pairs[i][1]])
      if (params[pairs[i][1]] !== undefined && params[pairs[i][1]] !== null && isFinite(v)) out[pairs[i][0]] = v
    }
  }
  return out
}

// Every accel value: those in the header (conf, may be null), else defaults.
function accelValues(conf, defaults) {
  var out = {}
  for (var k in defaults) {
    out[k] = conf && conf[k] !== undefined ? conf[k] : defaults[k]
  }
  return out
}

// `mac-trackpad-accel set ...` arguments, every value explicit.
function buildSetArgs(values) {
  var args = ["set"]
  for (var i = 0; i < ACCEL_OPTIONS.length; i++) {
    args.push(ACCEL_OPTIONS[i][1], formatNumber(values[ACCEL_OPTIONS[i][0]]))
  }
  return args
}

// daemon.json text -> { ok, data, error }. Empty or missing is {}.
function parseDaemon(text) {
  if (!String(text || "").trim()) return { ok: true, data: {}, error: "" }
  var data
  try {
    data = JSON.parse(text)
  } catch (e) {
    return { ok: false, data: {}, error: "not valid JSON (" + e.message + ")" }
  }
  if (!data || typeof data !== "object" || Array.isArray(data))
    return { ok: false, data: {}, error: "top level is not a JSON object" }
  return { ok: true, data: data, error: "" }
}

// A switch's value from daemon.json data (default true where missing or not
// a boolean, like the daemon).
function switchValue(data, key) {
  var v = data ? data[key] : undefined
  if (typeof v === "boolean") return v
  return key !== DRAG_KEY // inertia defaults on, three finger drag off
}

// daemon.json text with only key set to the boolean value; every other key
// kept, in order (new keys appended). { ok, text, error }.
function setSwitch(text, key, value) {
  var parsed = parseDaemon(text)
  if (!parsed.ok) return { ok: false, text: "", error: parsed.error }
  parsed.data[key] = value === true
  return { ok: true, text: JSON.stringify(parsed.data, null, 4) + "\n", error: "" }
}

// The last line of a process's output, for the status line.
function lastLine(text) {
  var lines = String(text || "").trim().split(/\r?\n/)
  return lines[lines.length - 1] || ""
}
